create extension if not exists pg_trgm;

create table if not exists public.erp_ajuda_documentos (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  titulo text not null,
  resumo text not null,
  conteudo text not null,
  palavras_chave text[] not null default '{}',
  rota text,
  publico boolean not null default true,
  ordem integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_erp_ajuda_documentos_keywords on public.erp_ajuda_documentos using gin (palavras_chave);
create index if not exists idx_erp_ajuda_documentos_titulo_trgm on public.erp_ajuda_documentos using gin (titulo gin_trgm_ops);

alter table public.erp_ajuda_documentos enable row level security;

drop policy if exists erp_ajuda_public_read on public.erp_ajuda_documentos;
create policy erp_ajuda_public_read on public.erp_ajuda_documentos for select to anon, authenticated using (publico = true);

on conflict (slug) do update set titulo=excluded.titulo,resumo=excluded.resumo,conteudo=excluded.conteudo,palavras_chave=excluded.palavras_chave,rota=excluded.rota,ordem=excluded.ordem,publico=true,updated_at=now();
